package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type EmpRec struct { // 01 EMP-REC, 17 bytes
	ErId   string          // PIC X(5) @0 len=5
	ErDept string          // PIC X(3) @5 len=3
	ErHours decimal.Decimal // PIC 9(3)V9 @8 len=4
	ErRate decimal.Decimal // PIC 9(3)V99 @12 len=5
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string // PIC X len=1 = "N"
var WsFirstFlag string // PIC X len=1 = "Y"
var WsPrevDept string // PIC X(3) len=3 = SPACES
var WsRegHours decimal.Decimal // PIC 9(3)V9 len=4 = 0
var WsOtHours decimal.Decimal // PIC 9(3)V9 len=4 = 0
var WsGross decimal.Decimal // PIC 9(7)V99 len=9 = 0
var WsDeptTotal decimal.Decimal // PIC 9(9)V99 len=11 = 0
var WsDeptCount int64 // PIC 9(3) len=3 = 0
var WsGrandTotal decimal.Decimal // PIC 9(11)V99 len=13 = 0
var WsGrandCount int64 // PIC 9(5) len=5 = 0
var WsHoursEd string // PIC ZZ9.9 len=5
var WsRateEd string // PIC ZZ9.99 len=6
var WsGrossEd string // PIC Z,ZZZ,ZZ9.99 len=12
var WsDeptEd string // PIC ZZZ,ZZZ,ZZ9.99 len=14
var WsGrandEd string // PIC ZZ,ZZZ,ZZZ,ZZ9.99 len=17

var EmpRecVar EmpRec
var empFileLines []string
var empFileIdx int

func parseNumericField(s string, scale int) decimal.Decimal {
	cleaned := make([]byte, len(s))
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c >= '0' && c <= '9' {
			cleaned[i] = c
		} else if c == ' ' {
			cleaned[i] = '0'
		} else {
			cleaned[i] = '0'
		}
	}
	str := string(cleaned)
	if len(str) == 0 {
		return decimal.NewFromInt(0)
	}
	d := decimal.RequireFromString(str)
	return d.Shift(int32(-scale))
}

func storeDecimal(val decimal.Decimal, intDigits int, scale int, rounded bool) decimal.Decimal {
	var t decimal.Decimal
	if rounded {
		t = val.Round(int32(scale))
	} else {
		t = val.Truncate(int32(scale))
	}
	totalDigits := intDigits + scale
	scaled := t.Shift(int32(scale))
	neg := scaled.IsNegative()
	if neg {
		scaled = scaled.Neg()
	}
	scaled = scaled.Truncate(0)
	s := scaled.StringFixed(0)
	// scaled 0 gives "0"
	if len(s) > totalDigits {
		s = s[len(s)-totalDigits:]
	}
	var resultScaled decimal.Decimal
	if s == "" {
		resultScaled = decimal.NewFromInt(0)
	} else {
		// s may be "0" or digits with leading zeros; RequireFromString handles it
		// ensure s is not empty and contains only digits (it does)
		resultScaled = decimal.RequireFromString(s)
	}
	if neg {
		resultScaled = resultScaled.Neg()
	}
	return resultScaled.Shift(int32(-scale))
}

func storeInt(v int64, digits int) int64 {
	if digits <= 0 {
		return v
	}
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	if mod == 0 {
		return v
	}
	// keep low-order digits, for positive values simple modulo
	if v >= 0 {
		return v % mod
	}
	return v % mod
}

func formatCount(v int64, width int) string {
	mod := int64(1)
	for i := 0; i < width; i++ {
		mod *= 10
	}
	if mod != 0 {
		v = v % mod
		if v < 0 {
			v = -v
		}
	}
	return fmt.Sprintf("%0*d", width, v)
}

func formatEdited(picture string, val decimal.Decimal) string {
	dotPos := strings.Index(picture, ".")
	if dotPos < 0 {
		return picture
	}
	intMask := picture[:dotPos]
	fracMask := picture[dotPos+1:]
	fracDigits := len(fracMask)
	intDigitSlots := 0
	for _, ch := range intMask {
		if ch == 'Z' || ch == '9' {
			intDigitSlots++
		}
	}
	truncated := val.Truncate(int32(fracDigits))
	sFixed := truncated.StringFixed(int32(fracDigits))
	parts := strings.Split(sFixed, ".")
	intStr := parts[0]
	fracStr := ""
	if fracDigits > 0 {
		if len(parts) > 1 {
			fracStr = parts[1]
		} else {
			fracStr = strings.Repeat("0", fracDigits)
		}
		if len(fracStr) < fracDigits {
			fracStr = fracStr + strings.Repeat("0", fracDigits-len(fracStr))
		} else if len(fracStr) > fracDigits {
			fracStr = fracStr[:fracDigits]
		}
	}
	sign := ""
	if len(intStr) > 0 && intStr[0] == '-' {
		sign = "-"
		intStr = intStr[1:]
	}
	if len(intStr) > intDigitSlots {
		intStr = intStr[len(intStr)-intDigitSlots:]
	} else if len(intStr) < intDigitSlots {
		intStr = strings.Repeat("0", intDigitSlots-len(intStr)) + intStr
	}
	intFormatted := make([]byte, len(intMask))
	digitIdx := 0
	for i := 0; i < len(intMask); i++ {
		ch := intMask[i]
		if ch == 'Z' || ch == '9' {
			intFormatted[i] = intStr[digitIdx]
			digitIdx++
		} else {
			intFormatted[i] = byte(ch)
		}
	}
	suppressing := true
	for i := 0; i < len(intMask); i++ {
		maskCh := intMask[i]
		if maskCh == 'Z' {
			if suppressing {
				if intFormatted[i] == '0' {
					intFormatted[i] = ' '
				} else {
					suppressing = false
				}
			}
		} else if maskCh == '9' {
			if suppressing {
				suppressing = false
			}
		} else if maskCh == ',' {
			if suppressing {
				intFormatted[i] = ' '
			}
		}
	}
	result := string(intFormatted) + "." + fracStr
	if sign != "" {
		// not expected for this program; prepend '-' if needed
		// try to place sign in first space
		placed := false
		b := []byte(result)
		for i := 0; i < len(b); i++ {
			if b[i] == ' ' {
				// look ahead for digit
				continue
			}
			break
		}
		_ = placed
		result = sign + result
		if len(result) > len(picture) {
			result = result[len(result)-len(picture):]
		}
	}
	return result
}

func ReadPara() {
	if empFileIdx >= len(empFileLines) {
		WsEofFlag = "Y"
		return
	}
	line := empFileLines[empFileIdx]
	empFileIdx++
	if len(line) < 17 {
		line = line + strings.Repeat(" ", 17-len(line))
	} else if len(line) > 17 {
		line = line[:17]
	}
	EmpRecVar.ErId = line[0:5]
	EmpRecVar.ErDept = line[5:8]
	EmpRecVar.ErHours = parseNumericField(line[8:12], 1)
	EmpRecVar.ErRate = parseNumericField(line[12:17], 2)
}

func ProcessPara() {
	if WsFirstFlag == "Y" {
		WsPrevDept = EmpRecVar.ErDept
		WsFirstFlag = "N"
	} else {
		if EmpRecVar.ErDept != WsPrevDept {
			DeptBreakPara()
			WsPrevDept = EmpRecVar.ErDept
		}
	}
	PayPara()
	ReadPara()
}

func PayPara() {
	if EmpRecVar.ErHours.Cmp(decimal.NewFromInt(40)) > 0 {
		WsRegHours = storeDecimal(decimal.NewFromInt(40), 3, 1, false)
		diff := EmpRecVar.ErHours.Sub(decimal.NewFromInt(40))
		WsOtHours = storeDecimal(diff, 3, 1, false)
	} else {
		WsRegHours = storeDecimal(EmpRecVar.ErHours, 3, 1, false)
		WsOtHours = storeDecimal(decimal.NewFromInt(0), 3, 1, false)
	}
	onePointFive := decimal.RequireFromString("1.5")
	term1 := WsRegHours.Mul(EmpRecVar.ErRate)
	term2 := WsOtHours.Mul(EmpRecVar.ErRate).Mul(onePointFive)
	grossRaw := term1.Add(term2)
	WsGross = storeDecimal(grossRaw, 7, 2, true)
	WsDeptTotal = storeDecimal(WsDeptTotal.Add(WsGross), 9, 2, false)
	WsDeptCount = storeInt(WsDeptCount+1, 3)
	WsGrandTotal = storeDecimal(WsGrandTotal.Add(WsGross), 11, 2, false)
	WsGrandCount = storeInt(WsGrandCount+1, 5)
	WsHoursEd = formatEdited("ZZ9.9", EmpRecVar.ErHours)
	WsRateEd = formatEdited("ZZ9.99", EmpRecVar.ErRate)
	WsGrossEd = formatEdited("Z,ZZZ,ZZ9.99", WsGross)
	line := EmpRecVar.ErId + " " + EmpRecVar.ErDept + " " + WsHoursEd + " " + WsRateEd + " " + WsGrossEd
	fmt.Println(line)
}

func DeptBreakPara() {
	WsDeptEd = formatEdited("ZZZ,ZZZ,ZZ9.99", WsDeptTotal)
	countStr := formatCount(WsDeptCount, 3)
	line := "  DEPT " + WsPrevDept + " EMPLOYEES: " + countStr + " TOTAL: " + WsDeptEd
	fmt.Println(line)
	WsDeptTotal = storeDecimal(decimal.NewFromInt(0), 9, 2, false)
	WsDeptCount = storeInt(0, 3)
}

func GrandPara() {
	WsGrandEd = formatEdited("ZZ,ZZZ,ZZZ,ZZ9.99", WsGrandTotal)
	countStr := formatCount(WsGrandCount, 5)
	line := "GRAND TOTAL (" + countStr + "): " + WsGrandEd
	fmt.Println(line)
}

func MainPara() {
	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	if WsFirstFlag != "Y" {
		DeptBreakPara()
	}
	GrandPara()
}

func main() {
	WsEofFlag = "N"
	WsFirstFlag = "Y"
	WsPrevDept = strings.Repeat(" ", 3)
	WsRegHours = decimal.NewFromInt(0)
	WsOtHours = decimal.NewFromInt(0)
	WsGross = decimal.NewFromInt(0)
	WsDeptTotal = decimal.NewFromInt(0)
	WsDeptCount = 0
	WsGrandTotal = decimal.NewFromInt(0)
	WsGrandCount = 0

	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	scanner := bufio.NewScanner(f)
	empFileLines = []string{}
	for scanner.Scan() {
		empFileLines = append(empFileLines, scanner.Text())
	}
	if err := scanner.Err(); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	f.Close()
	empFileIdx = 0
	MainPara()
}
